import json
from pathlib import Path
wanted = {'CATALOGUE-PAID-BUYER-REPLY-REHEARSAL', 'NLNET-OPEN-CALL-DELIVERY-FIT', 'ITCH-SQLITE-EXACT-CANDIDATE-REVIEW', 'SQLITE-PAID-EDUCATIONAL-COMMISSION'}
def visit(item):
    if isinstance(item, list):
        for value in item:
            visit(value)
    elif isinstance(item, dict):
        if item.get('mission_id') in wanted and 'status' in item:
            print(json.dumps({key: item.get(key) for key in ('mission_id', 'status', 'agent_id', 'lease_expires_at', 'evidence')}))
        else:
            for value in item.values():
                visit(value)
for page in sorted(Path('world/pages').glob('missions-*.json')):
    visit(json.loads(page.read_text()))
path = Path('products/services/nlnet-csv-milestone/suite-evidence.json')
if path.is_file():
    data = json.loads(path.read_text())
    print(json.dumps({'milestone_suite': str(path), 'evidence': data}, ensure_ascii=False)[:5000])
else:
    print('Milestone suite absent from selected snapshot')
